begin;

do $$
declare
  v_sector uuid;
  v_category uuid;
  v_body jsonb;
  v_text text;
  v_id uuid;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_category from public.categories where slug='addiction-treatment-care' and sector_id=v_sector;
  if v_sector is null or v_category is null then
    raise exception 'addiction treatment taxonomy is missing';
  end if;

  v_body := jsonb_build_object('blocks', jsonb_build_array(
    jsonb_build_object('type','paragraph','text','علاج اضطرابات استخدام المواد ليس إجراءً واحدًا ولا برنامجًا ثابتًا يصلح لكل شخص. الخطة الجيدة تبدأ بتحديد الاضطراب أو نمط الاستخدام، خطر التسمم أو الانسحاب، الصحة النفسية والجسدية المصاحبة، الأدوية الحالية، الوظيفة اليومية، البيئة الأسرية والاجتماعية، ثم اختيار تدخلات ثبتت فائدتها للحالة المحددة. لذلك لا ينبغي أن يكون السؤال الأول: ما أفضل مركز أو دواء؟ بل: ما المشكلة التي نحاول علاجها، ما مستوى الخطر الآن، وما المزيج الذي يرفع احتمال البقاء في الرعاية ويخفض الوفاة والضرر ويحسن الوظيفة؟ هذا الدليل يشرح منطق الاختيار ولا يقدم وصفة فردية أو جرعات.'),

    jsonb_build_object('type','heading','level',2,'text','1. العلاج يبدأ بتقييم متعدد المجالات لا باسم المادة وحده'),
    jsonb_build_object('type','paragraph','text','قد يستخدم شخصان المادة نفسها وتختلف حاجتهما العلاجية جذريًا. أحدهما قد يكون في خطر انسحاب يحتاج مراقبة طبية، والآخر قد لا يواجه انسحابًا مهددًا للحياة لكنه يعاني اكتئابًا شديدًا أو فقدان سكن أو استخدام مواد متعددة أو تاريخ جرعات زائدة. لهذا تؤكد معايير منظمة الصحة العالمية ومكتب الأمم المتحدة أن التقييم يجب أن يشمل نمط الاستخدام وشدته، العلامات الجسدية والنفسية، المخاطر الفورية، الدعم الاجتماعي، تاريخ العلاج، الاستعداد للتغيير والعوائق العملية أمام الوصول. التشخيص المهني مهم، لكن العلاج لا ينتظر دائمًا اكتمال كل التفاصيل إذا كان هناك خطر عاجل؛ تُعالج الأولويات الحرجة أولًا ثم تُستكمل الصورة.'),
    jsonb_build_object('type','paragraph','text','تقدير الشدة لا يعني الحكم الأخلاقي على الشخص. هو أداة لمطابقة التدخل مع الحاجة. الاستخدام المتقطع مع ضرر محدود قد يستفيد من تدخل مختصر ومتابعة، بينما الاضطراب الأكثر شدة أو المصحوب بانسحاب خطير أو أمراض نفسية وجسدية معقدة قد يحتاج فريقًا متعدد التخصصات أو مستوى رعاية أكثر كثافة. كما يجب فحص المواد المتعددة لأن وجود الكحول أو المهدئات أو الأفيونات مع مواد أخرى قد يغير الخطر ومسار العلاج. ويُعاد التقييم خلال الرحلة؛ فالخطة التي كانت مناسبة في الأسبوع الأول قد تحتاج تخفيفًا أو تصعيدًا بعد تغير الأعراض أو السكن أو الدعم أو الالتزام.'),

    jsonb_build_object('type','heading','level',2,'text','2. العلاج الدوائي: قوي عندما توجد دلالة، وغير متاح لكل اضطراب'),
    jsonb_build_object('type','paragraph','text','من الأخطاء الشائعة التعامل مع أدوية علاج الإدمان كأنها مجرد بديل للمادة أو كأن قبولها دليل على ضعف الإرادة. في بعض الاضطرابات تمثل الأدوية جزءًا أساسيًا من العلاج وتخفض مخاطر مهمة، بينما في اضطرابات أخرى لا يوجد حتى الآن دواء معتمد أو مدعوم بما يكفي ليكون علاجًا نوعيًا. لذلك يجب ربط الدواء بالتشخيص والهدف والأدلة، لا بشعار عام عن العلاج الدوائي. كما أن اختيار الدواء يتأثر بالحمل ووظائف الكبد والكلى والأدوية الأخرى واحتمال التداخلات والتفضيلات وإمكانية المتابعة، ولهذا لا يمكن تحويل قائمة أسماء إلى وصفة صالحة للجميع.'),

    jsonb_build_object('type','heading','level',3,'text','اضطراب استخدام الأفيونات: لماذا العلاج الناهض محور أساسي؟'),
    jsonb_build_object('type','paragraph','text','أعادت منظمة الصحة العالمية في تحديثاتها الحديثة التأكيد على أن العلاج الصياني بناهضات الأفيون مثل الميثادون والبوبرينورفين يملك أقوى قاعدة أدلة لمعظم المرضى المصابين باعتماد الأفيونات، ويرتبط بتحسن الاستبقاء في العلاج وخفض الاستخدام غير الطبي والوفيات وبعض الأضرار الصحية والاجتماعية. توجد أيضًا خيارات مضادة لمستقبلات الأفيون مثل النالتريكسون في سياقات مختارة. النقطة السريرية المهمة هي أن إزالة السموم وحدها ليست بديلًا عن علاج الاضطراب؛ بعد فقدان التحمل قد يرتفع خطر الجرعة الزائدة إذا عاد الشخص إلى الاستخدام، ولذلك يجب أن تكون أي مرحلة انسحاب مرتبطة بخطة علاج واستمرارية ووقاية من الجرعة الزائدة. اختيار النهج يتم مع فريق مؤهل ووفق الأنظمة المحلية.'),

    jsonb_build_object('type','heading','level',3,'text','اضطراب استخدام الكحول: دمج العلاج النفسي والدوائي'),
    jsonb_build_object('type','paragraph','text','إرشادات mhGAP الحديثة توصي بإتاحة التدخلات النفسية والدوائية مجتمعة للبالغين المصابين باعتماد الكحول عندما تكون مناسبة. تشمل الخيارات الدوائية المستخدمة في أنظمة صحية مختلفة أدوية مثل النالتريكسون والأكامبروسيت والديسلفيرام، لكن ملاءمة كل خيار تختلف باختلاف الهدف السريري والحالة الطبية والالتزام والتداخلات. كما يجب فصل أدوية إدارة الانسحاب الحاد عن أدوية علاج الاضطراب على المدى الأطول؛ السيطرة على أعراض الانسحاب ليست نهاية العلاج. يجب أن تشمل الخطة أيضًا معالجة النوم والمزاج والأمراض الكبدية أو العصبية إن وجدت، وتخطيط العودة إلى العمل والأسرة، ومتابعة مؤشرات التحسن بدل الاكتفاء بسؤال هل شرب الشخص أم لم يشرب.'),

    jsonb_build_object('type','heading','level',3,'text','النيكوتين والتبغ: دليل دوائي وسلوكي واضح'),
    jsonb_build_object('type','paragraph','text','أصدرت منظمة الصحة العالمية في 2024 أول دليل سريري شامل للإقلاع عن التبغ لدى البالغين، ودعمت الجمع بين التدخلات السلوكية والعلاجات الدوائية المناسبة. من الخيارات التي تذكرها الإرشادات العلاج ببدائل النيكوتين والفارينيكلين والبوبروبيون والسيتيسين حيث تكون متاحة ومناسبة. وجود اعتماد على النيكوتين مع اضطراب استخدام مادة أخرى لا يعني تأجيل علاجه تلقائيًا؛ يمكن إدخاله ضمن خطة التعافي مع مراعاة أولويات الشخص. التدخل القصير من مقدم الرعاية، الدعم الأكثر كثافة، والدعم الرقمي يمكن أن تكون أجزاء من منظومة الإقلاع. الاختيار الفردي يحتاج مراجعة التاريخ الصحي والمنتج المستخدم والتجارب السابقة والتفضيلات.'),

    jsonb_build_object('type','heading','level',3,'text','المنبهات والقنب والمهدئات والسلوكيات الإدمانية'),
    jsonb_build_object('type','paragraph','text','لا ينبغي افتراض أن لكل اضطراب دواءً نوعيًا مماثلًا لما هو متاح في الأفيونات أو الكحول أو التبغ. في اضطراب استخدام المنبهات، يركز الدليل الحديث بدرجة كبيرة على التدخلات السلوكية، ويبرز التعزيز الطارئ كأحد أكثر الأساليب المدروسة، مع استمرار البحث في خيارات دوائية لبعض الحالات دون تحويل النتائج الناشئة إلى وصفة عامة. القنب كذلك يعتمد علاجه أساسًا على تدخلات نفسية وسلوكية ودعم الوظيفة والمصاحبات. أما المهدئات والبنزوديازيبينات فتحتاج اهتمامًا خاصًا بالاعتماد والانسحاب والتاريخ الدوائي؛ التغييرات الدوائية يجب أن تكون سريرية ومراقبة. وفي القمار والألعاب الرقمية لا يكون العلاج الدوائي هو الأساس الافتراضي للاضطراب نفسه، بل تُقيّم المصاحبات ويُستخدم العلاج النفسي والسلوكي الملائم.'),

    jsonb_build_object('type','heading','level',2,'text','3. العلاج النفسي والسلوكي: اختيار التقنية بحسب الهدف'),
    jsonb_build_object('type','paragraph','text','مصطلح العلاج النفسي لا يعني جلسة دعم غير محددة. التدخل الجيد يحدد الهدف والآلية وطريقة القياس. المقابلة التحفيزية أو التعزيز التحفيزي يمكن أن يساعدا في استكشاف التردد وبناء أسباب التغيير بدل الدخول في جدال. العلاج المعرفي السلوكي يعمل على ربط المواقف والأفكار والانفعالات بالسلوك، وبناء مهارات للتعامل مع الرغبة والضغط وحل المشكلات. التدخلات الأسرية أو الزوجية قد تكون مفيدة في سياقات محددة عندما تكون العلاقات جزءًا من البيئة التي تحمي التعافي أو تعرقله. الدعم الجماعي والمساندة المتبادلة قد يضيفان شبكة اجتماعية، لكنهما لا يحلان محل الرعاية الطبية عندما توجد حاجة إليها.'),
    jsonb_build_object('type','heading','level',3,'text','التعزيز الطارئ في اضطراب استخدام المنبهات'),
    jsonb_build_object('type','paragraph','text','التعزيز الطارئ Contingency Management يستخدم حوافز منظمة وشفافة مرتبطة بسلوك علاجي محدد قابل للتحقق، مثل الحضور أو تحقيق هدف متفق عليه ضمن البرنامج. المراجعات المنهجية والإرشادات الحديثة تجعله من أكثر التدخلات الواعدة والمدروسة في اضطراب استخدام المنبهات. نجاحه لا يعتمد على فكرة مكافأة الشخص على كونه جيدًا؛ بل على مبادئ تعلم سلوكي وتصميم بروتوكول واضح ونزاهة التطبيق. يجب أن تراجع البرامج قانونية الحوافز وآلية القياس وتجنب الإذلال أو العقوبات التي تزيد الانقطاع عن العلاج.'),
    jsonb_build_object('type','heading','level',3,'text','العلاج المعرفي السلوكي والدافعية والأسرة'),
    jsonb_build_object('type','paragraph','text','لا توجد تقنية نفسية واحدة تتفوق في كل الحالات. العلاج المعرفي السلوكي يكون مفيدًا عندما يكون الهدف بناء مهارات للتعرف إلى المحفزات وتعديل الروتين والتعامل مع الانفعالات وحل المشكلات. التدخلات التحفيزية مفيدة عندما تكون الدافعية متذبذبة، وهو أمر طبيعي في مسار التغيير. إشراك الأسرة يجب أن يعتمد على موافقة الشخص وسلامة البيئة؛ وجود عنف أو سيطرة أو تهديد يغيّر طريقة العمل ولا يجعل الجلسة الأسرية خيارًا تلقائيًا. كما ينبغي علاج الاضطرابات النفسية المصاحبة بدل انتظار أن تختفي كلها بعد توقف المادة، مع تمييز الأعراض المرتبطة بالتسمم أو الانسحاب عن اضطرابات مستقلة تحتاج متابعة.'),

    jsonb_build_object('type','heading','level',2,'text','4. اختيار مستوى الرعاية: الأقل تقييدًا الذي يظل آمنًا وفعالًا'),
    jsonb_build_object('type','paragraph','text','ليس العلاج الداخلي أكثر جودة لمجرد أنه أكثر كثافة، وليس العلاج الخارجي مناسبًا دائمًا لمجرد أنه يحافظ على الحياة اليومية. القرار يعتمد على خطر الانسحاب والتسمم، الاستقرار الطبي والنفسي، القدرة على حماية النفس، السكن والدعم، تاريخ الانقطاع عن العلاج، ومدى توفر رعاية موثوقة في المجتمع. قد يبدأ بعض الأشخاص في الرعاية الأولية أو العيادات الخارجية، بينما يحتاج آخرون إلى مراقبة مكثفة أو إقامة قصيرة أو خدمة متخصصة. الهدف هو مطابقة المستوى مع الحاجة ثم التحرك بين المستويات دون انقطاع غير ضروري.'),
    jsonb_build_object('type','paragraph','text','الانتقال بين الخدمات نقطة ضعف متكررة. الخروج من الطوارئ أو برنامج انسحاب أو إقامة يجب ألا يكون نهاية الملف؛ يلزم موعد تالٍ واضح، معلومات محدثة عن الأدوية، خطة للتعامل مع المخاطر، جهة مسؤولة عن المتابعة، وطريقة لاستعادة الاتصال إذا فات الموعد. الانقطاع بعد فترة امتناع قد يكون خطيرًا خصوصًا في الأفيونات بسبب تغير التحمل. لذلك تُقاس جودة النظام أيضًا بسرعة الربط بعد الخروج واستمرارية العلاج، لا بعدد الأسرة أو مدة الإقامة فقط.'),

    jsonb_build_object('type','heading','level',2,'text','5. الحالات المصاحبة: العلاج المتكامل أفضل من مسارين لا يتحدثان'),
    jsonb_build_object('type','paragraph','text','الاكتئاب والقلق واضطراب ما بعد الصدمة والذهان واضطراب فرط الحركة والألم المزمن وأمراض الكبد والقلب والعدوى قد تتقاطع مع اضطرابات استخدام المواد. فصل كل مشكلة في مؤسسة مختلفة دون تنسيق قد يترك الشخص بين أنظمة متوازية. التقييم المتكامل يسأل: ما العرض الذي يحتاج تدخلًا الآن؟ هل توجد أدوية أو أمراض تغير قرار علاج الإدمان؟ هل هناك عرض نفسي يزيد خطر الانتحار أو العودة للاستخدام؟ هل يحتاج الشخص فحصًا لعدوى أو رعاية ألم أو دعم نوم؟ التنسيق لا يعني أن مختصًا واحدًا يفعل كل شيء؛ بل أن المسؤوليات والمعلومات الأساسية والإحالات لا تتعارض.'),
    jsonb_build_object('type','paragraph','text','اللغة مهمة هنا. نسب كل عرض إلى الإدمان قد يفوّت اضطرابًا قابلًا للعلاج، ونسب كل عرض إلى مرض نفسي مستقل قد يتجاهل أثر التسمم والانسحاب. التسلسل الزمني للأعراض، فترات الامتناع، تاريخ الأسرة، الأدوية، النوم والمزاج تساعد على بناء فرضيات تُراجع مع الوقت. بعض القرارات لا يمكن حسمها في زيارة واحدة. لهذا يكون القياس المتكرر أفضل من تشخيص سريع غير قابل للمراجعة.'),

    jsonb_build_object('type','heading','level',2,'text','6. التعافي ليس الامتناع وحده: ما النتائج التي يجب قياسها؟'),
    jsonb_build_object('type','paragraph','text','الامتناع قد يكون هدفًا مركزيًا لكثير من الناس، لكنه ليس المؤشر الوحيد على جودة العلاج. يمكن قياس البقاء في العلاج، انخفاض الجرعات الزائدة أو زيارات الطوارئ، تحسن النوم والصحة الجسدية والمزاج، انتظام الدواء الموصوف، استقرار السكن، تحسن العلاقات، العودة إلى الدراسة أو العمل، انخفاض السلوكيات الخطرة، والقدرة على طلب المساعدة مبكرًا. إذا عرض مركز علاجي نسبة نجاح واحدة دون تعريف النجاح أو مدة المتابعة أو عدد من فُقدت متابعتهم، فهذه ليست نتيجة كافية للحكم.'),
    jsonb_build_object('type','paragraph','text','النتائج يجب أن تُقاس على فترات لا عند الخروج فقط. قد يبدو البرنامج ناجحًا يوم المغادرة ثم تضيع الاستمرارية خلال الأسابيع التالية. كما يجب تفسير التعثر بوصفه معلومة عن الخطة والسياق لا حكمًا نهائيًا على الشخص. هل تغير مستوى الخطر؟ هل ظهرت مصاحبة غير معالجة؟ هل انقطع الدواء؟ هل عاد الشخص إلى بيئة عالية التعرض؟ هل كانت الأهداف غير واقعية؟ مراجعة هذه الأسئلة تقود إلى تعديل العلاج بدل تكرار النموذج نفسه.'),

    jsonb_build_object('type','heading','level',2,'text','7. كيف تختار مقدم علاج وتكشف الادعاءات الضعيفة؟'),
    jsonb_build_object('type','paragraph','text','اسأل عن الترخيص والمؤهلات، طريقة التقييم، كيفية التعامل مع الطوارئ والانسحاب، توفر الأدوية الموصى بها عندما تكون مناسبة، الخبرة بالمصاحبات، سياسة إشراك الأسرة والخصوصية، وخطة المتابعة بعد الخروج. اسأل أيضًا كيف يقيس البرنامج نتائجه وما تعريفه للنجاح. العبارات مثل علاج مضمون أو شفاء نهائي أو نسبة نجاح شبه كاملة تحتاج دليلًا قابلًا للتدقيق، لا شهادة تسويقية. الجودة لا تعني الفخامة أو طول الإقامة؛ تعني سلامة، كفاءة، دليلًا، احترامًا، استمرارية وقدرة على تعديل الخطة.'),
    jsonb_build_object('type','paragraph','text','وجود علاج روحي أو أنشطة لياقة أو دعم أقران يمكن أن يكون ذا قيمة لبعض الأشخاص، لكنه لا ينبغي أن يُستخدم لإخفاء غياب التقييم الطبي أو التدخلات القائمة على الدليل عندما تكون مطلوبة. وبالمثل، التقنية الرقمية قد تحسن المتابعة والتذكير والوصول، لكنها لا تحل محل الرعاية العاجلة أو الفحص السريري في الحالات المعقدة. اسأل دائمًا: ما المشكلة التي يحلها هذا المكون؟ ما الدليل؟ من يشرف عليه؟ وكيف نعرف إن كان مفيدًا لهذا الشخص؟'),

    jsonb_build_object('type','heading','level',2,'text','8. الفئات التي تحتاج تكييفًا لا نسخة مصغرة من برنامج البالغين'),
    jsonb_build_object('type','paragraph','text','المراهقون واليافعون يحتاجون تقييمًا للنمو والأسرة والمدرسة والخصوصية والموافقة وفق القانون المحلي. الحمل وما بعد الولادة يحتاجان موازنة صحة الأم والجنين أو الرضيع واستمرارية العلاج وعدم قطع أدوية فعالة بصورة ارتجالية. كبار السن قد تكون لديهم أدوية متعددة وسقوط واضطراب معرفي وأمراض مزمنة تغير العرض والخطر. الأشخاص ذوو الاحتياجات الخاصة قد يحتاجون لغة مبسطة أو تواصلًا بديلًا أو دعم قرار وحماية من الاستغلال. من لا يملك سكنًا مستقرًا قد يفشل في برنامج ممتاز نظريًا إذا كانت الخطة تفترض هاتفًا ثابتًا ونقلًا آمنًا وتخزينًا مناسبًا للأدوية.'),
    jsonb_build_object('type','paragraph','text','التكييف لا يعني خفض معيار الرعاية، بل إزالة العوائق التي تمنع الاستفادة منها. قد يكون الحل موعدًا أكثر مرونة، تنسيقًا مع الرعاية الأولية، تواصلًا يسهل فهمه، خدمة عن بعد عند ملاءمتها، متابعة متنقلة، دعم نقل أو سكن، أو دمج خدمات العدوى والصحة النفسية. يجب أن تظل الحقوق والكرامة والسرية والموافقة جزءًا من جودة العلاج لا امتيازًا إضافيًا.'),

    jsonb_build_object('type','heading','level',2,'text','9. أسئلة عملية قبل بدء أي خطة علاج'),
    jsonb_build_object('type','list','ordered',true,'items',jsonb_build_array(
      'ما التشخيص أو نمط المشكلة الذي تستهدفه الخطة، وما الأدلة التي تدعمه؟',
      'ما الأخطار الفورية التي يجب التعامل معها قبل بقية الأهداف؟',
      'هل يوجد علاج دوائي مثبت لهذه الحالة، وهل توجد أسباب تجعل خيارًا معينًا غير مناسب؟',
      'ما التدخل النفسي أو السلوكي المحدد، وما الهدف الذي سيقيسه؟',
      'لماذا اختير هذا المستوى من الرعاية، ومتى نرفعه أو نخفضه؟',
      'كيف ستُعالج الاكتئاب أو القلق أو الألم أو الأمراض الطبية إن وجدت؟',
      'ما خطة الانتقال والمتابعة إذا خرج الشخص من الطوارئ أو الإقامة؟',
      'ما مؤشرات التحسن خلال الأسابيع والأشهر القادمة، ومن يراجعها؟'
    )),
    jsonb_build_object('type','paragraph','text','الإجابة الجيدة لا يجب أن تكون معقدة؛ ينبغي أن يستطيع الفريق شرح منطق الخطة بلغة مفهومة، وأن يبين ما هو مؤكد وما هو غير مؤكد وما الذي سيغير القرار. إذا تغيرت الحالة، تتغير الخطة. هذه المرونة ليست علامة ضعف بل جزء من العلاج المبني على القياس.'),

    jsonb_build_object('type','heading','level',2,'text','10. خلاصة القرار: علاج مناسب، قابل للاستمرار، وقابل للقياس'),
    jsonb_build_object('type','paragraph','text','أفضل خطة ليست الأطول أو الأغلى أو الأكثر صرامة، بل الخطة التي تطابق شدة الحالة والمخاطر وتستخدم تدخلات مناسبة للدليل وتستطيع الاحتفاظ بالشخص في الرعاية وتحسين حياته. في الأفيونات قد يكون العلاج الدوائي طويل المدى عنصرًا منقذًا للحياة. في الكحول والتبغ توجد خيارات دوائية وسلوكية فعالة. في اضطرابات أخرى قد يكون العلاج السلوكي هو العمود الفقري مع معالجة المصاحبات. وفي كل الحالات تحتاج الاستمرارية إلى نظام انتقال ودعم وأسرة أو أقران عند رغبة الشخص ومؤشرات نتائج واضحة. العلاج عملية مراجعة مستمرة، وليس عقدًا لبرنامج واحد.'),

    jsonb_build_object('type','faq','items',jsonb_build_array(
      jsonb_build_object('question','هل أدوية علاج الإدمان تستبدل إدمانًا بإدمان؟','answer','لا يصح تعميم ذلك. بعض الأدوية، وخصوصًا العلاج الصياني بناهضات الأفيون، تُستخدم ضمن ممارسة طبية منظمة ولها أدلة قوية على خفض مخاطر مهمة وتحسين الاستبقاء. وجود اعتماد جسدي دوائي منضبط ليس مساويًا لاضطراب استخدام يتصف بفقد السيطرة والضرر. القرار يبقى سريريًا ويعتمد على التشخيص والهدف والمخاطر والتفضيلات.'),
      jsonb_build_object('question','هل إزالة السموم تكفي لعلاج الإدمان؟','answer','غالبًا لا. إدارة الانسحاب قد تكون مرحلة سلامة مهمة، لكنها لا تعالج وحدها اضطراب الاستخدام أو العوامل النفسية والاجتماعية والمصاحبات. بعد الانسحاب يلزم ربط الشخص بالعلاج المناسب والمتابعة وخطة تقليل خطر العودة والجرعة الزائدة، مع إعادة تقييم مستوى الرعاية.'),
      jsonb_build_object('question','هل كل اضطرابات الإدمان لها دواء فعال؟','answer','لا. توجد أدوية مثبتة أو معتمدة في أنظمة صحية متعددة لاضطرابات مثل الأفيونات والكحول والتبغ، بينما تعتمد اضطرابات أخرى بدرجة أكبر على التدخلات النفسية والسلوكية ودعم الوظيفة ومعالجة المصاحبات. غياب دواء نوعي لا يعني غياب علاج فعال.'),
      jsonb_build_object('question','متى يكون العلاج الداخلي أفضل من الخارجي؟','answer','عندما تجعل المخاطر الطبية أو النفسية أو الانسحاب أو البيئة غير الآمنة الرعاية الخارجية غير كافية، أو عندما يحتاج الشخص مراقبة وكثافة علاجية لا يمكن توفيرها بأمان في المجتمع. لا توجد قاعدة تجعل الإقامة أفضل للجميع؛ المستوى يختار وفق الحاجة ويعاد تقييمه.'),
      jsonb_build_object('question','هل الانتكاس يعني أن الدواء أو العلاج النفسي فشل؟','answer','ليس بالضرورة. العودة للاستخدام تستدعي فحص ما تغير: التعرض للمحفزات، انقطاع الدواء أو المتابعة، ألم أو أرق، اضطراب نفسي، سكن غير مستقر أو مستوى رعاية غير مناسب. قد تحتاج الخطة تعديلًا أو كثافة أعلى أو تدخلًا مختلفًا بدل الحكم على العلاج كله بالفشل.'),
      jsonb_build_object('question','كيف أعرف أن مركز علاج الإدمان موثوق؟','answer','ابحث عن ترخيص ومؤهلات واضحة، تقييم منهجي، تعامل آمن مع الانسحاب والطوارئ، إتاحة العلاج الدوائي والنفسي القائم على الدليل عندما يلزم، احترام الخصوصية والحقوق، خطة متابعة بعد الخروج ونتائج قابلة للتعريف والقياس. تجنب الاعتماد على نسبة نجاح دعائية بلا منهج.'),
      jsonb_build_object('question','هل يمكن علاج الإدمان والاكتئاب أو القلق معًا؟','answer','نعم، وغالبًا يكون التنسيق ضروريًا لأن كل حالة قد تؤثر في الأخرى وفي السلامة والالتزام. يجب تقييم التسلسل الزمني للأعراض، أثر التسمم والانسحاب، وخطر إيذاء النفس، ثم بناء علاج متكامل بدل مطالبة الشخص بإنهاء مشكلة كاملة قبل بدء علاج الأخرى.'),
      jsonb_build_object('question','ما أهم سؤال أطرحه على الفريق قبل بدء العلاج؟','answer','اسأل: لماذا هذه الخطة مناسبة لهذه الحالة تحديدًا، وما الذي سنقيسه لنعرف أنها تعمل؟ الإجابة الجيدة تربط التشخيص والمخاطر بالدليل ومستوى الرعاية والمتابعة، وتوضح متى ستتغير الخطة إذا لم تتحقق النتائج المتوقعة.')
    ))
