  select string_agg(
    case b->>'type'
      when 'paragraph' then b->>'text'
      when 'heading' then b->>'text'
      when 'list' then (select string_agg(value,E'\n') from jsonb_array_elements_text(b->'items'))
      when 'faq' then (select string_agg((x->>'question')||E'\n'||(x->>'answer'),E'\n\n') from jsonb_array_elements(b->'items') x)
      else ''
    end,
    E'\n\n'
  ) into v_text
  from jsonb_array_elements(v_body->'blocks') b;

